  const schedule = lookSchedule(stratumSize, alpha, perStratumDelta, n0, maxLooks);
  const perLookDelta =
    bound === "betting" ? perStratumDelta : perStratumDelta / schedule.length;
  const looks: AdaptiveLook[] = [];
