      // Truncate lambda so 1 + lam*(m - X) stays positive for any X in [0,1].
      lam = Math.min(lam, 0.5 / Math.max(1 - m, 1e-9));
      capital *= 1 + lam * (m - flips[i]!);
      if (capital <= 0) return true;
      if (capital > maxCapital) maxCapital = capital;
