export interface PromptDeltaV1 {
  added: string[];
  removed: string[];
  /** Content words (lowercased, deduped) from added+removed spans. */
  deltaTerms: string[];
}

const STOPWORDS = new Set(
  "a an the is are was were be being been do does did of in on at to from by for with without and or not no nor but if then else this that these those it its as such into over under out up down about between per each every any all some most more less than only merely just also very really consider considering judge judging based work works working person people row data one who whose".split(
    " ",
  ),
);

export function tokenizeContent(text: string): string[] {
  return [
    ...new Set(
      text
        .toLowerCase()
        .replaceAll(/\{\{[^}]*\}\}/g, " ")
        .split(/[^a-z0-9+#.]+/)
        .filter((w) => w.length > 2 && !STOPWORDS.has(w)),
    ),
  ];
}

/**
 * Word-level LCS diff over the two prompts; returns added/removed spans and
 * the content-term delta used for row-interaction scoring.
 */
export function diffPrompts(a: string, b: string): PromptDeltaV1 {
  const aw = a.split(/\s+/).filter(Boolean);
  const bw = b.split(/\s+/).filter(Boolean);
  const m = aw.length;
  const n = bw.length;
  const dp: number[][] = Array.from({ length: m + 1 }, () =>
    new Array<number>(n + 1).fill(0),
  );
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      dp[i]![j] =
        aw[i] === bw[j]
          ? dp[i + 1]![j + 1]! + 1
          : Math.max(dp[i + 1]![j]!, dp[i]![j + 1]!);
    }
  }
  const removed: string[] = [];
  const added: string[] = [];
  let i = 0;
  let j = 0;
  while (i < m && j < n) {
    if (aw[i] === bw[j]) {
      i++;
      j++;
    } else if (dp[i + 1]![j]! >= dp[i]![j + 1]!) {
      removed.push(aw[i]!);
      i++;
    } else {
      added.push(bw[j]!);
      j++;
    }
  }
  removed.push(...aw.slice(i));
  added.push(...bw.slice(j));
  const deltaTerms = [
    ...new Set([
      ...tokenizeContent(added.join(" ")),
      ...tokenizeContent(removed.join(" ")),
    ]),
  ];
  return { added, removed, deltaTerms };
}

/** How many delta terms appear in this row's bound content. */
export function overlapScore(boundText: string, delta: PromptDeltaV1): number {
  if (delta.deltaTerms.length === 0) return 0;
  const rowTerms = new Set(tokenizeContent(boundText));
  let hits = 0;
  for (const t of delta.deltaTerms) if (rowTerms.has(t)) hits++;
  return hits;
}

