  const K = input.strata.length;
  const perStratumDelta = input.delta / Math.max(1, K);
  return input.strata.map((s) => {
    const upper = ebUpperBound(s.flipSample, perStratumDelta);
    const flips = s.flipSample.reduce((a, b) => a + b, 0);
