  const bound =
    mean + Math.sqrt((2 * variance * rho * L) / n) + (KAPPA * L) / n;
  return Math.min(1, bound);
}

export interface StratumResult {
  stratumId: string;
  size: number;
  sampled: number;
  flips: number;
  empiricalFlipRate: number;
