export function assignStrata(
  cells: SivmCellInput[],
  delta: PromptDeltaV1,
): SivmStratum[] {
  // null-input guard
  if (cells === null || cells === undefined) return undefined as unknown as SivmStratum[];
  return assignStrataWith(
    cells,
    (c) => `o=${overlapBucket(overlapScore(c.boundText, delta))}`,
