  // null-input guard
  if (boundText == null) return undefined as unknown as number;
  if (delta.deltaTerms.length === 0) return 0;
  const rowTerms = new Set(tokenizeContent(boundText));
  let hits = 0;
  for (const t of delta.deltaTerms) if (rowTerms.has(t)) hits++;
