export function lookSchedule(
  stratumSize: number,
  alpha: number,
  perStratumDelta: number,
  n0 = 45,
  maxLooks = 4,
): number[] {
  const perLookDelta = perStratumDelta / maxLooks;
  const need = minSampleForZeroFlips(alpha, perLookDelta);
  const looks: number[] = [];
